  revenue - LAG(revenue) OVER (ORDER BY day) AS change,
  SUM(revenue) OVER (
    ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW
  ) AS week_total
FROM daily_sales;

